DO $exp$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Curso de Farmacoterapia de la Hipertensión Arterial$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Curso de Farmacoterapia de la Hipertensión Arterial$t$;
    RETURN;
  END IF;

  -- 01. Caso: tos por enalapril, edema por amlodipino e interacción con simvastatina
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Tres problemas en una sola receta","texto":"Una paciente con hipertensión y dislipidemia toma enalapril, amlodipino y simvastatina 40 mg. Consulta por tos seca, tobillos hinchados y dolor muscular. Los tres síntomas pueden tener relación con los medicamentos, pero no se resuelven cambiando todo a la vez. Hay que priorizar, confirmar y ajustar con criterio."},"objetivos":["Identificar la tos por IECA y el edema por amlodipino.","Reconocer la interacción amlodipino-simvastatina.","Priorizar problemas y proponer cambios seguros.","Educar y coordinar el seguimiento."],"conceptos":[{"icono":"AlertTriangle","termino":"Tos por IECA","definicion":"Tos seca persistente por enalapril; mejora al cambiar a ARA-II."},{"icono":"Droplets","termino":"Edema por amlodipino","definicion":"Edema periférico por vasodilatación; no responde bien a diuréticos."},{"icono":"Pill","termino":"Simvastatina","definicion":"Estatina metabolizada por CYP3A4; con amlodipino no debe superar 20 mg al día."},{"icono":"ShieldCheck","termino":"Prioridad","definicion":"Ordenar los problemas por gravedad y riesgo antes de intervenir."}],"secciones":[{"titulo":"Separar los problemas","parrafos":["La tos seca es típica del enalapril y mejora al cambiar a un ARA-II. El edema de tobillos es frecuente con amlodipino y no suele responder a diuréticos. El dolor muscular puede ser una reacción a la estatina, pero también puede tener otras causas. No se debe atribuir todo al mismo fármaco sin evaluar.","La interacción amlodipino-simvastatina es relevante: el amlodipino inhibe parcialmente CYP3A4 y aumenta la exposición a simvastatina. La dosis de simvastatina no debe superar 20 mg al día. Si el paciente toma 40 mg, hay que revisar y ajustar."]},{"titulo":"Priorizar y proponer","parrafos":["Primero se evalúa el dolor muscular: si hay debilidad, orina oscura o CK elevada, se suspende la estatina y se consulta. La tos y el edema afectan la calidad de vida, pero no son emergencias. Se propone cambiar el enalapril por un ARA-II, reducir el amlodipino o cambiar a otra clase y ajustar la simvastatina.","Los cambios deben ser escalonados para identificar el efecto de cada uno. Se revisan presión, síntomas, CK y función renal. La paciente debe entender qué síntoma corresponde a qué cambio."]},{"titulo":"Educación y seguimiento","parrafos":["La educación incluye reportar dolor muscular intenso, orina oscura, hinchazón de labios o dificultad para respirar. Se revisa la técnica de medición y la adherencia. El QF documenta la intervención y la comunica al equipo.","La meta es controlar la presión y los lípidos sin efectos adversos. Un cambio bien explicado mejora la confianza y la adherencia."]}],"errores":[{"error":"Mantener simvastatina 40 mg con amlodipino.","correccion":"El límite es 20 mg al día."},{"error":"Atribuir el edema a insuficiencia cardíaca sin evaluar.","correccion":"El amlodipino es una causa frecuente."},{"error":"Cambiar todo a la vez.","correccion":"La secuencia permite evaluar cada cambio."}],"comprueba":[{"pregunta":"¿Qué fármaco causa tos seca?","respuesta":"El enalapril."},{"pregunta":"¿Qué límite tiene simvastatina con amlodipino?","respuesta":"20 mg al día."},{"pregunta":"¿Qué hacer con edema por amlodipino?","respuesta":"Reducir la dosis o cambiar de clase; no suele responder a diuréticos."}],"resumen":["Tres síntomas, tres causas posibles.","La interacción amlodipino-simvastatina exige ajuste.","La secuencia evita confusiones.","La educación cubre signos de alarma."],"referencias":[{"cita":"European Society of Cardiology. 2024 ESC Guidelines for the management of elevated blood pressure and hypertension. Eur Heart J. 2024.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Hypertension"},{"cita":"AEMPS-CIMA. Ficha técnica de Amlodipino besilato.","url":"https://cima.aemps.es/cima/dochtml/ft/65460/FT_65460.html"}],"imagenes":[{"ubicacion":"Sección del caso","descripcion":"Paciente con tos, tobillos hinchados y dolor muscular, con tres medicamentos señalados.","alt":"Caso de tos, edema e interacción con simvastatina"}],"keywords":["tos enalapril edema amlodipino","amlodipino simvastatina interacción","caso clínico hipertensión","efectos adversos antihipertensivos"],"mapa":{"centro":"Tres problemas","ramas":[{"titulo":"Tos","icono":"AlertTriangle","nodos":["Enalapril","Cambiar a ARA-II","Revisar"]},{"titulo":"Edema","icono":"Droplets","nodos":["Amlodipino","Reducir o cambiar","No diurético"]},{"titulo":"Músculo","icono":"Activity","nodos":["Simvastatina","Dolor","CK"]},{"titulo":"Plan","icono":"Target","nodos":["Priorizar","Cambiar","Seguir"]}]},"proceso":{"titulo":"Abordaje de tres problemas","intro":"","pasos":[{"titulo":"Evaluar gravedad","detalle":"Dolor muscular, debilidad, disnea o angioedema.","icono":"AlertTriangle","evidencia":"Evaluación."},{"titulo":"Revisar interacción","detalle":"Amlodipino con simvastatina 40 mg.","icono":"Search","evidencia":"Revisión."},{"titulo":"Proponer cambios","detalle":"ARA-II, ajuste de amlodipino y estatina.","icono":"RefreshCw","evidencia":"Nota."},{"titulo":"Educar","detalle":"Síntomas de alarma y cambios.","icono":"Users","evidencia":"Educación."},{"titulo":"Seguir","detalle":"Presión, CK y tolerancia.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Dolor muscular con simvastatina 40","contexto":"Paciente con amlodipino 10 mg, simvastatina 40 mg, dolor muscular difuso y CK normal. Tos seca con enalapril.","pregunta":"¿Qué ajuste es más razonable?","opciones":[{"texto":"Mantener simvastatina 40 y añadir un diurético.","correcta":false,"retro":"La dosis de simvastatina supera el límite con amlodipino y el diurético no corrige el edema."},{"texto":"Reducir simvastatina a 20 mg o cambiar de estatina, cambiar enalapril por ARA-II y revisar el edema.","correcta":true,"retro":"Se abordan las tres causas con cambios escalonados y seguimiento."},{"texto":"Suspender todo.","correcta":false,"retro":"Se ajusta, no se abandona."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Caso: tos por enalapril, edema por amlodipino e interacción con simvastatina$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Caso: tos por enalapril, edema por amlodipino e interacción con simvastatina$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 02. Introducción a la unidad: diuréticos, betabloqueadores y fármacos de segunda línea
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"No todos son primera línea","texto":"Los diuréticos y betabloqueadores son pilares de la hipertensión, pero no todos los pacientes se benefician igual. Las tiazidas son útiles en hipertensión y osteoporosis, los betabloqueadores en angina e insuficiencia cardíaca, y los antagonistas de mineralocorticoides en HTA resistente. Elegir bien exige conocer las indicaciones preferentes."},"objetivos":["Diferenciar diuréticos, betabloqueadores y fármacos de segunda línea.","Reconocer las indicaciones preferentes de cada grupo.","Identificar los efectos adversos y controles.","Seleccionar según comorbilidad y perfil del paciente."],"conceptos":[{"icono":"Droplets","termino":"Tiazida","definicion":"Diurético que reduce el volumen y la resistencia vascular; útil en hipertensión."},{"icono":"Activity","termino":"Betabloqueador","definicion":"Reduce frecuencia y contractilidad; indicado en angina, IC y postinfarto."},{"icono":"Pill","termino":"Antagonista mineralocorticoide","definicion":"Espironolactona o eplerenona; útil en HTA resistente e insuficiencia cardíaca."},{"icono":"Target","termino":"Indicación preferente","definicion":"Comorbilidad que hace que un grupo sea especialmente útil."}],"secciones":[{"titulo":"Tiazidas y similares","parrafos":["Las tiazidas reducen el volumen plasmático y, con el tiempo, la resistencia vascular. Son eficaces, económicas y útiles en hipertensión, especialmente en personas mayores y en osteoporosis. Pueden causar hipopotasemia, hiponatremia, hiperglucemia, hiperuricemia y hipercalcemia.","La clortalidona es más potente y prolongada que la hidroclorotiazida; la indapamida tiene un perfil similar. La elección depende de la respuesta, los electrolitos y la tolerancia."]},{"titulo":"Betabloqueadores","parrafos":["Los betabloqueadores reducen la frecuencia cardiaca y la contractilidad. Son de elección en angina, postinfarto, insuficiencia cardíaca con fracción de eyección reducida y algunas arritmias. No son primera línea para hipertensión sin indicación específica, pero pueden combinarse.","Los cardioselectivos como bisoprolol y metoprolol tienen menos efectos bronquiales. El carvedilol tiene efecto alfa y se usa en insuficiencia cardíaca. Se evitan en asma grave y se usan con precaución en bradicardia."]},{"titulo":"Otras opciones","parrafos":["Los antagonistas de mineralocorticoides, como la espironolactona, son útiles en HTA resistente y en insuficiencia cardíaca. Requieren control de potasio y función renal. Los alfabloqueadores, los agonistas centrales y los vasodilatadores directos se reservan para situaciones específicas.","La elección se basa en la comorbilidad, la edad, la función renal, los electrolitos y la tolerancia. El QF puede revisar la indicación y los controles."]}],"errores":[{"error":"Usar betabloqueador en asma grave.","correccion":"Puede broncoespasmo; se evita o se elige cardioselectivo con precaución."},{"error":"No controlar potasio con tiazidas.","correccion":"Hipopotasemia es frecuente."},{"error":"Usar espironolactona sin revisar función renal.","correccion":"Riesgo de hiperpotasemia."}],"comprueba":[{"pregunta":"¿Cuándo se prefiere un betabloqueador?","respuesta":"En angina, postinfarto, IC con FE reducida y algunas arritmias."},{"pregunta":"¿Qué efecto adverso tienen las tiazidas?","respuesta":"Hipopotasemia, hiponatremia e hiperuricemia."},{"pregunta":"¿Qué control requiere espironolactona?","respuesta":"Potasio y función renal."}],"resumen":["Los grupos de segunda línea tienen **indicaciones preferentes**.","Las tiazidas son útiles en HTA y osteoporosis.","Los betabloqueadores en angina e IC.","La espironolactona en HTA resistente."],"referencias":[{"cita":"European Society of Cardiology. 2024 ESC Guidelines for the management of elevated blood pressure and hypertension. Eur Heart J. 2024.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Hypertension"},{"cita":"AEMPS-CIMA. Ficha técnica de Hidroclorotiazida.","url":"https://cima.aemps.es/cima/dochtml/ft/90833/FT_90833.html"}],"imagenes":[{"ubicacion":"Sección de grupos","descripcion":"Cuatro columnas con tiazida, betabloqueador, espironolactona y otros, con sus indicaciones.","alt":"Fármacos de segunda línea para hipertensión"}],"keywords":["diuréticos hipertensión","betabloqueadores hipertensión","tiazidas efectos adversos","espironolactona hta resistente"],"mapa":{"centro":"Segunda línea","ramas":[{"titulo":"Tiazidas","icono":"Droplets","nodos":["HTA","Osteoporosis","Hipopotasemia"]},{"titulo":"Betabloqueadores","icono":"Activity","nodos":["Angina","IC","Postinfarto"]},{"titulo":"Mineralocorticoides","icono":"Pill","nodos":["HTA resistente","IC","Potasio"]},{"titulo":"Otros","icono":"Layers","nodos":["Alfa","Centrales","Nuevas moléculas"]}]},"proceso":{"titulo":"Cómo elegir un fármaco de segunda línea","intro":"","pasos":[{"titulo":"Revisar comorbilidad","detalle":"Angina, IC, osteoporosis, ERC o HTA resistente.","icono":"Search","evidencia":"Evaluación."},{"titulo":"Revisar electrolitos","detalle":"Potasio, sodio y función renal.","icono":"Droplets","evidencia":"Resultados."},{"titulo":"Elegir","detalle":"Tiazida, betabloqueador o mineralocorticoide.","icono":"Pill","evidencia":"Selección."},{"titulo":"Educar","detalle":"Efectos adversos y controles.","icono":"Users","evidencia":"Educación."},{"titulo":"Seguir","detalle":"Presión, electrolitos y tolerancia.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Angina e hipertensión","contexto":"Paciente con angina estable e hipertensión, presión 148/92, sin asma ni bradicardia.","pregunta":"¿Qué grupo tiene indicación preferente?","opciones":[{"texto":"Un betabloqueador.","correcta":true,"retro":"En angina, el betabloqueador reduce la demanda de oxígeno y los eventos."},{"texto":"Una tiazida sola.","correcta":false,"retro":"Puede ayudar a la presión, pero no trata la angina."},{"texto":"Un alfaagonista central.","correcta":false,"retro":"No es primera elección en angina."}]}}$j$::jsonb;
