  -- 03. Tiazidas y similares: hidroclorotiazida, clortalidona e indapamida
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La tiazida que baja el potasio","texto":"Una paciente mayor inicia hidroclorotiazida y a las semanas llega con debilidad, calambres y potasio de 3,1 mEq/L. La tiazida es eficaz y barata, pero requiere control de electrolitos. Conocer las diferencias entre hidroclorotiazida, clortalidona e indapamida permite elegir y vigilar."},"objetivos":["Explicar el mecanismo y las indicaciones de las tiazidas.","Comparar hidroclorotiazida, clortalidona e indapamida.","Reconocer y prevenir alteraciones electrolíticas.","Aplicar controles y educación al paciente."],"conceptos":[{"icono":"Droplets","termino":"Tiazida","definicion":"Diurético que inhibe el cotransportador sodio-cloro en el túbulo distal."},{"icono":"Activity","termino":"Hipopotasemia","definicion":"Potasio bajo por pérdida urinaria; puede causar debilidad y arritmias."},{"icono":"AlertTriangle","termino":"Hiponatremia","definicion":"Sodio bajo, sobre todo en personas mayores; puede causar confusión."},{"icono":"Target","termino":"Elección","definicion":"Clortalidona es más potente y prolongada; indapamida tiene perfil similar."}],"secciones":[{"titulo":"Mecanismo y usos","parrafos":["Las tiazidas inhiben el cotransportador sodio-cloro en el túbulo distal, aumentan la excreción de sodio y agua y reducen el volumen. Con el uso crónico, también disminuyen la resistencia vascular. Son eficaces en hipertensión, sobre todo en personas mayores, y pueden reducir el riesgo de fracturas.","La hidroclorotiazida es la más usada, pero la clortalidona tiene mayor potencia y duración. La indapamida es una alternativa con perfil metabólico similar. La elección depende de la respuesta, los electrolitos y el costo."]},{"titulo":"Efectos adversos","parrafos":["La hipopotasemia es frecuente y puede causar debilidad, calambres y arritmias. La hiponatremia es más común en personas mayores y puede causar confusión o caídas. También pueden elevar la glucosa, el ácido úrico y el calcio, y causar hiperuricemia o gota.","Se controlan electrolitos y función renal al iniciar y después de ajustar. La educación incluye síntomas de hipopotasemia y deshidratación. No se deben indicar suplementos de potasio sin control."]},{"titulo":"Elección y combinación","parrafos":["Las tiazidas se combinan con IECA, ARA-II o calcioantagonistas. La combinación con un bloqueador del sistema renina-angiotensina puede reducir el riesgo de hipopotasemia. En insuficiencia renal avanzada pierden eficacia y se prefiere un diurético de asa.","El QF puede revisar la adherencia, la presión y los electrolitos. La automedida ayuda a evaluar la respuesta y evitar la hipotensión."]}],"errores":[{"error":"No controlar potasio.","correccion":"Es un efecto frecuente y peligroso."},{"error":"Usar tiazida en insuficiencia renal avanzada.","correccion":"Pierde eficacia; se prefiere diurético de asa."},{"error":"No revisar sodio en adultos mayores.","correccion":"La hiponatremia puede causar confusión y caídas."}],"comprueba":[{"pregunta":"¿Dónde actúan las tiazidas?","respuesta":"En el túbulo distal, inhibiendo el cotransportador sodio-cloro."},{"pregunta":"¿Qué electrolitos se controlan?","respuesta":"Potasio y sodio."},{"pregunta":"¿Qué tiazida es más potente?","respuesta":"La clortalidona."}],"resumen":["Las tiazidas son eficaces y económicas.","Causan hipopotasemia e hiponatremia.","Se controlan electrolitos y función renal.","La combinación con IECA/ARA-II reduce el riesgo."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Hidroclorotiazida.","url":"https://cima.aemps.es/cima/dochtml/ft/90833/FT_90833.html"},{"cita":"European Society of Cardiology. 2024 ESC Guidelines for the management of elevated blood pressure and hypertension. Eur Heart J. 2024.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Hypertension"}],"imagenes":[{"ubicacion":"Sección de electrolitos","descripcion":"Paciente con calambres y un resultado de potasio bajo, junto a una caja de hidroclorotiazida.","alt":"Hipopotasemia por tiazida"}],"keywords":["hidroclorotiazida dosis","tiazidas hipopotasemia","clortalidona hipertensión","indapamida","electrolitos tiazidas"],"mapa":{"centro":"Tiazidas","ramas":[{"titulo":"Mecanismo","icono":"Droplets","nodos":["Túbulo distal","Menos sodio","Menos volumen"]},{"titulo":"Fármacos","icono":"Layers","nodos":["Hidroclorotiazida","Clortalidona","Indapamida"]},{"titulo":"Efectos","icono":"AlertTriangle","nodos":["Hipopotasemia","Hiponatremia","Hiperuricemia"]},{"titulo":"Control","icono":"LineChart","nodos":["Potasio","Sodio","Creatinina"]}]},"proceso":{"titulo":"Cómo iniciar una tiazida","intro":"","pasos":[{"titulo":"Indicación","detalle":"HTA, osteoporosis o edema.","icono":"Target","evidencia":"Indicación."},{"titulo":"Electrolitos","detalle":"Potasio, sodio y creatinina.","icono":"Droplets","evidencia":"Resultados."},{"titulo":"Dosis","detalle":"Hidroclorotiazida 12,5-25 mg.","icono":"Pill","evidencia":"Esquema."},{"titulo":"Educar","detalle":"Síntomas de hipopotasemia y deshidratación.","icono":"Users","evidencia":"Educación."},{"titulo":"Seguir","detalle":"Presión y electrolitos.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Potasio 3,1","contexto":"Paciente con hidroclorotiazida 25 mg, debilidad y potasio 3,1 mEq/L.","pregunta":"¿Qué hacer?","opciones":[{"texto":"Ignorar porque está asintomática.","correcta":false,"retro":"La hipopotasemia puede causar arritmias; requiere corrección."},{"texto":"Revisar la dosis, corregir el potasio y considerar combinación con IECA/ARA-II o cambio.","correcta":true,"retro":"Se corrige y se ajusta el esquema con control."},{"texto":"Aumentar la tiazida.","correcta":false,"retro":"Empeora la hipopotasemia."}]}}$j$::jsonb;
