  -- 04. Antagonistas de mineralocorticoides, otros ahorradores de potasio y diuréticos de asa
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"El diurético que retiene potasio","texto":"La espironolactona es útil en HTA resistente y en insuficiencia cardíaca, pero puede elevar el potasio peligrosamente. Los diuréticos de asa son potentes y se usan en edema o insuficiencia renal avanzada. Conocer sus diferencias evita hiperpotasemia y deshidratación."},"objetivos":["Diferenciar antagonistas de mineralocorticoides, ahorradores de potasio y diuréticos de asa.","Reconocer indicaciones y riesgos.","Aplicar controles de potasio y función renal.","Elegir según el contexto clínico."],"conceptos":[{"icono":"Pill","termino":"Espironolactona","definicion":"Antagonista de aldosterona; útil en HTA resistente e insuficiencia cardíaca."},{"icono":"Droplets","termino":"Ahorrador de potasio","definicion":"Reduce la excreción de potasio; riesgo de hiperpotasemia."},{"icono":"Activity","termino":"Diurético de asa","definicion":"Potente, actúa en el asa de Henle; útil en edema e insuficiencia renal."},{"icono":"AlertTriangle","termino":"Hiperpotasemia","definicion":"Potasio alto; puede causar arritmias graves."}],"secciones":[{"titulo":"Antagonistas de mineralocorticoides","parrafos":["La espironolactona bloquea el receptor de aldosterona y reduce la retención de sodio y la excreción de potasio. Es útil en HTA resistente, insuficiencia cardíaca y aldosteronismo. La eplerenona tiene menos efectos antiandrogénicos. Ambas pueden causar hiperpotasemia, sobre todo con IECA/ARA-II o enfermedad renal.","Se controlan potasio y creatinina antes y después de iniciar. Se evitan suplementos de potasio sin control. La ginecomastia y las alteraciones menstruales son efectos de la espironolactona."]},{"titulo":"Ahorradores y diuréticos de asa","parrafos":["La amilorida y el triamtereno son ahorradores de potasio menos potentes. La furosemida actúa en el asa de Henle, es potente y se usa en edema, insuficiencia cardíaca e insuficiencia renal avanzada. Puede causar hipopotasemia, hipovolemia y ototoxicidad.","La combinación de tiazida con ahorrador de potasio puede equilibrar los electrolitos. En insuficiencia renal avanzada, las tiazidas pierden eficacia y se prefiere furosemida."]},{"titulo":"Elección y seguridad","parrafos":["La elección depende del volumen, la función renal, el potasio y la indicación. La espironolactona se usa en HTA resistente después de optimizar otros fármacos. La furosemida se usa cuando hay congestión o insuficiencia renal.","El QF puede revisar la dosis, los electrolitos y la adherencia. La educación incluye signos de deshidratación e hiperpotasemia."]}],"errores":[{"error":"Usar espironolactona sin control de potasio.","correccion":"Riesgo de hiperpotasemia."},{"error":"Usar tiazida en ERC avanzada.","correccion":"Pierde eficacia."},{"error":"No revisar volumen con furosemida.","correccion":"Puede causar deshidratación."}],"comprueba":[{"pregunta":"¿Qué efecto adverso tiene la espironolactona?","respuesta":"Hiperpotasemia y efectos antiandrogénicos."},{"pregunta":"¿Dónde actúa la furosemida?","respuesta":"En el asa de Henle."},{"pregunta":"¿Qué se controla?","respuesta":"Potasio, creatinina y volumen."}],"resumen":["Espironolactona: **HTA resistente** y IC.","Ahorradores: riesgo de hiperpotasemia.","Furosemida: edema y ERC avanzada.","Electrolitos y volumen se controlan."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Espironolactona Accord 25 mg comprimidos recubiertos con película EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/81034/FT_81034.html"},{"cita":"European Society of Cardiology. 2024 ESC Guidelines for the management of elevated blood pressure and hypertension. Eur Heart J. 2024.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Hypertension"}],"imagenes":[{"ubicacion":"Sección de seguridad","descripcion":"Paciente con edema y un resultado de potasio alto, junto a espironolactona y furosemida.","alt":"Diuréticos ahorradores y de asa"}],"keywords":["espironolactona hipertensión","diurético ahorrador de potasio","furosemida hipertensión","hiperpotasemia espironolactona"],"mapa":{"centro":"Diuréticos especiales","ramas":[{"titulo":"Mineralocorticoides","icono":"Pill","nodos":["Espironolactona","HTA resistente","Potasio"]},{"titulo":"Ahorradores","icono":"Droplets","nodos":["Amilorida","Triamtereno","Potasio"]},{"titulo":"Asa","icono":"Activity","nodos":["Furosemida","Edema","Hipopotasemia"]},{"titulo":"Control","icono":"LineChart","nodos":["Potasio","Creatinina","Volumen"]}]},"proceso":{"titulo":"Cómo iniciar un diurético especial","intro":"","pasos":[{"titulo":"Indicación","detalle":"HTA resistente, IC, edema o ERC.","icono":"Target","evidencia":"Indicación."},{"titulo":"Revisar función","detalle":"TFG, potasio y volumen.","icono":"Droplets","evidencia":"Resultados."},{"titulo":"Elegir","detalle":"Espironolactona, ahorrador o furosemida.","icono":"Pill","evidencia":"Selección."},{"titulo":"Educar","detalle":"Potasio, deshidratación y síntomas.","icono":"Users","evidencia":"Educación."},{"titulo":"Seguir","detalle":"Electrolitos, peso y presión.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"HTA resistente y potasio 5,4","contexto":"Paciente con IECA, amlodipino y tiazida; se añade espironolactona. Potasio 5,4 mEq/L.","pregunta":"¿Qué hacer?","opciones":[{"texto":"Aumentar la espironolactona.","correcta":false,"retro":"Empeora la hiperpotasemia."},{"texto":"Revisar la dosis, suspender o reducir y controlar potasio y función renal.","correcta":true,"retro":"La hiperpotasemia requiere ajuste inmediato."},{"texto":"Añadir un suplemento de potasio.","correcta":false,"retro":"Es peligroso."}]}}$j$::jsonb;
