  -- 05. Betabloqueadores: indicaciones preferentes y diferencias entre moléculas
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"El betabloqueador correcto para el paciente correcto","texto":"No todos los betabloqueadores son iguales. Bisoprolol, metoprolol, carvedilol y atenolol difieren en cardioselectividad, efecto alfa y evidencia. Elegir el adecuado en angina, insuficiencia cardíaca o postinfarto mejora el pronóstico; elegir mal puede empeorar la bradicardia o el broncoespasmo."},"objetivos":["Clasificar los betabloqueadores por selectividad y efecto.","Reconocer las indicaciones preferentes.","Identificar efectos adversos y precauciones.","Elegir según la comorbilidad."],"conceptos":[{"icono":"Activity","termino":"Cardioselectivo","definicion":"Bloquea preferentemente receptores beta-1; menos efecto bronquial."},{"icono":"Gauge","termino":"Vasodilatador","definicion":"Carvedilol bloquea alfa-1 y reduce la resistencia periférica."},{"icono":"Target","termino":"Indicación","definicion":"Angina, postinfarto, IC con FE reducida y arritmias."},{"icono":"AlertTriangle","termino":"Bradicardia","definicion":"Frecuencia baja; límite para titulación."}],"secciones":[{"titulo":"Diferencias entre moléculas","parrafos":["Los betabloqueadores cardioselectivos como bisoprolol, metoprolol y atenolol bloquean principalmente beta-1 y tienen menos efectos bronquiales. El carvedilol bloquea beta-1, beta-2 y alfa-1, lo que produce vasodilatación y se usa en insuficiencia cardíaca. El labetalol tiene efecto alfa y se usa en hipertensión del embarazo.","La evidencia en insuficiencia cardíaca con fracción de eyección reducida favorece bisoprolol, metoprolol succinato y carvedilol. En angina, los cardioselectivos son útiles. En postinfarto, reducen la mortalidad."]},{"titulo":"Indicaciones y precauciones","parrafos":["Se usan en angina, postinfarto, insuficiencia cardíaca estable y algunas arritmias. En hipertensión sin indicación específica no son primera línea, pero pueden combinarse. Se evitan en asma grave y se usan con precaución en bradicardia, bloqueo AV y enfermedad arterial periférica grave.","Pueden causar fatiga, bradicardia, hipotensión, disfunción sexual y broncoespasmo. No se suspenden bruscamente por el riesgo de angina o taquicardia de rebote."]},{"titulo":"Titulación y educación","parrafos":["En insuficiencia cardíaca se inicia con dosis baja y se titula cada dos a cuatro semanas. Se controlan frecuencia, presión, síntomas y función renal. La educación incluye no suspender abruptamente y reportar mareo o falta de aire.","El QF puede revisar la adherencia, la técnica de medición y las interacciones. La elección debe ser individualizada."]}],"errores":[{"error":"Suspender bruscamente.","correccion":"Riesgo de rebote; se reduce gradualmente."},{"error":"Usar betabloqueador no selectivo en asma.","correccion":"Puede broncoespasmo."},{"error":"No titular en IC.","correccion":"La dosis baja inicial es seguridad."}],"comprueba":[{"pregunta":"¿Cuál es cardioselectivo?","respuesta":"Bisoprolol, metoprolol y atenolol."},{"pregunta":"¿Cuál tiene efecto alfa?","respuesta":"Carvedilol y labetalol."},{"pregunta":"¿Dónde se usan con beneficio?","respuesta":"Angina, postinfarto e IC con FE reducida."}],"resumen":["No todos los betabloqueadores son iguales.","Los cardioselectivos tienen menos efecto bronquial.","Carvedilol tiene efecto alfa.","No se suspenden bruscamente."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Bisoprolol Cinfa 10 mg comprimidos EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/78905/FT_78905.html"},{"cita":"European Society of Cardiology. 2024 ESC Guidelines for the management of elevated blood pressure and hypertension. Eur Heart J. 2024.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Hypertension"}],"imagenes":[{"ubicacion":"Sección de diferencias","descripcion":"Comparación de bisoprolol, carvedilol y propranolol con selectividad y efectos.","alt":"Diferencias entre betabloqueadores"}],"keywords":["betabloqueadores hipertensión","bisoprolol dosis","carvedilol insuficiencia cardiaca","betabloqueador asma","betabloqueadores angina"],"mapa":{"centro":"Betabloqueadores","ramas":[{"titulo":"Cardioselectivos","icono":"Activity","nodos":["Bisoprolol","Metoprolol","Atenolol"]},{"titulo":"Vasodilatadores","icono":"Gauge","nodos":["Carvedilol","Labetalol","Alfa-1"]},{"titulo":"Indicaciones","icono":"Target","nodos":["Angina","IC","Postinfarto"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Bradicardia","Broncoespasmo","Fatiga"]}]},"proceso":{"titulo":"Cómo elegir un betabloqueador","intro":"","pasos":[{"titulo":"Indicación","detalle":"Angina, IC, postinfarto o arritmia.","icono":"Target","evidencia":"Indicación."},{"titulo":"Revisar vía aérea","detalle":"Asma o EPOC.","icono":"Wind","evidencia":"Evaluación."},{"titulo":"Elegir","detalle":"Cardioselectivo o vasodilatador.","icono":"Pill","evidencia":"Selección."},{"titulo":"Titular","detalle":"Dosis baja y aumento gradual.","icono":"RefreshCw","evidencia":"Esquema."},{"titulo":"Seguir","detalle":"Frecuencia, presión y síntomas.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Angina y asma leve","contexto":"Paciente con angina y asma leve, presión 146/90, frecuencia 88.","pregunta":"¿Qué opción es más razonable?","opciones":[{"texto":"Carvedilol a dosis alta.","correcta":false,"retro":"El bloqueo beta-2 puede empeorar el broncoespasmo."},{"texto":"Bisoprolol a dosis baja con vigilancia respiratoria.","correcta":true,"retro":"El cardioselectivo tiene menos efecto bronquial; se titula con cuidado."},{"texto":"Propranolol.","correcta":false,"retro":"No es cardioselectivo y puede empeorar el asma."}]}}$j$::jsonb;
