  -- 06. Otros antihipertensivos y nuevas moléculas para HTA resistente
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Cuando lo habitual no alcanza","texto":"Un paciente con HTA resistente ya toma tres fármacos, incluido un diurético, y la presión sigue alta. Además de revisar adherencia y causas secundarias, existen opciones como espironolactona, alfabloqueadores, agonistas centrales y nuevas moléculas. No son para todos, pero pueden cambiar el control."},"objetivos":["Reconocer las opciones de segunda y tercera línea.","Diferenciar alfabloqueadores, agonistas centrales y vasodilatadores.","Identificar el lugar de las nuevas moléculas.","Aplicar criterios de seguridad y seguimiento."],"conceptos":[{"icono":"Pill","termino":"Alfabloqueador","definicion":"Bloquea alfa-1 y reduce la resistencia vascular; útil en HTA resistente y próstata."},{"icono":"Network","termino":"Agonista central","definicion":"Reduce la actividad simpática; útil en HTA resistente, pero con efectos adversos."},{"icono":"Gauge","termino":"Vasodilatador directo","definicion":"Relaja el músculo liso vascular; se usa en situaciones específicas."},{"icono":"Target","termino":"HTA resistente","definicion":"Presión no controlada a pesar de tres fármacos, incluido un diurético, con adherencia confirmada."}],"secciones":[{"titulo":"Opciones clásicas","parrafos":["Los alfabloqueadores como doxazosina reducen la resistencia vascular y son útiles en HTA resistente y en síntomas prostáticos. Pueden causar hipotensión ortostática. Los agonistas centrales como clonidina y metildopa reducen la actividad simpática, pero causan sedación, boca seca y rebote si se suspenden.","La hidralazina y el minoxidil son vasodilatadores directos que causan retención de líquidos y taquicardia; se usan con diuréticos y betabloqueadores en situaciones específicas. No son de primera línea."]},{"titulo":"Nuevas moléculas","parrafos":["La investigación en hipertensión resistente incluye antagonistas de endotelina, como aprocitentan, y otras vías. Su lugar en la práctica depende de la aprobación, la disponibilidad y la evidencia. No sustituyen la revisión de adherencia y causas secundarias.","Antes de usar una opción avanzada, se confirma la resistencia con medición correcta y AMPA/MAPA, se revisa la adherencia y se descartan causas secundarias. La HTA resistente es un diagnóstico de exclusión."]},{"titulo":"Seguridad y seguimiento","parrafos":["Los alfabloqueadores requieren vigilancia de ortostatismo. Los agonistas centrales no se suspenden bruscamente. Los vasodilatadores directos pueden causar edema y taquicardia. Las nuevas moléculas requieren seguimiento especializado.","El QF puede revisar la adherencia, la técnica y las interacciones. La educación sobre efectos adversos mejora la tolerancia."]}],"errores":[{"error":"Diagnosticar resistencia sin confirmar adherencia.","correccion":"La pseudorresistencia es frecuente."},{"error":"Suspender clonidina bruscamente.","correccion":"Riesgo de rebote."},{"error":"Usar minoxidil sin diurético.","correccion":"Causa retención de líquidos."}],"comprueba":[{"pregunta":"¿Qué es HTA resistente?","respuesta":"Presión no controlada con tres fármacos, incluido un diurético, y adherencia confirmada."},{"pregunta":"¿Qué efecto tiene doxazosina?","respuesta":"Bloqueo alfa-1 y reducción de la resistencia vascular."},{"pregunta":"¿Qué riesgo tiene clonidina?","respuesta":"Sedación y rebote al suspender."}],"resumen":["Las opciones avanzadas requieren **confirmación**.","Los alfabloqueadores ayudan en próstata.","Los centrales tienen rebote.","Las nuevas moléculas son especializadas."],"referencias":[{"cita":"European Society of Cardiology. 2024 ESC Guidelines for the management of elevated blood pressure and hypertension. Eur Heart J. 2024.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Hypertension"},{"cita":"Williams B, MacDonald TM, Morant S, et al. Spironolactone versus placebo, bisoprolol, and doxazosin to determine the optimal treatment for drug-resistant hypertension (PATHWAY-2). Lancet. 2015;386(10008):2059-68.","url":"https://pubmed.ncbi.nlm.nih.gov/26314530/"}],"imagenes":[{"ubicacion":"Sección de opciones","descripcion":"Árbol de decisiones con espironolactona, doxazosina, clonidina y nuevas moléculas.","alt":"Opciones para hipertensión resistente"}],"keywords":["hipertensión resistente tratamiento","doxazosina hipertensión","clonidina hipertensión","aprocitentan","cuarta línea hipertensión"],"mapa":{"centro":"Opciones avanzadas","ramas":[{"titulo":"Alfa","icono":"Pill","nodos":["Doxazosina","Terazosina","Próstata"]},{"titulo":"Centrales","icono":"Network","nodos":["Clonidina","Metildopa","Sedación"]},{"titulo":"Vasodilatadores","icono":"Gauge","nodos":["Hidralazina","Minoxidil","Edema"]},{"titulo":"Nuevas","icono":"Sparkles","nodos":["Aprocitentan","Investigación"]}]},"proceso":{"titulo":"Cómo elegir una opción avanzada","intro":"","pasos":[{"titulo":"Confirmar resistencia","detalle":"Medición, AMPA/MAPA y adherencia.","icono":"Gauge","evidencia":"Confirmación."},{"titulo":"Descartar causas","detalle":"Apnea, aldosteronismo, renal, fármacos.","icono":"Search","evidencia":"Evaluación."},{"titulo":"Elegir","detalle":"Espironolactona, alfa o central.","icono":"Pill","evidencia":"Selección."},{"titulo":"Educar","detalle":"Ortostatismo, sedación y rebote.","icono":"Users","evidencia":"Educación."},{"titulo":"Seguir","detalle":"Presión, electrolitos y síntomas.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"HTA resistente y próstata","contexto":"Paciente con tres fármacos, presión 154/96, síntomas prostáticos y adherencia confirmada.","pregunta":"¿Qué opción es razonable?","opciones":[{"texto":"Doxazosina, con vigilancia de ortostatismo.","correcta":true,"retro":"El alfabloqueador ayuda a la presión y a los síntomas prostáticos."},{"texto":"Clonidina sin revisar adherencia.","correcta":false,"retro":"La resistencia debe confirmarse y la clonidina tiene efectos adversos."},{"texto":"Minoxidil como primera opción.","correcta":false,"retro":"No es primera línea y causa retención de líquidos."}]}}$j$::jsonb;
