  -- 07. Caso: hipopotasemia por tiazida y elección de betabloqueador en una paciente con angina
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Dos problemas, una paciente","texto":"Una mujer de 67 años con hipertensión y angina toma hidroclorotiazida, amlodipino y atenolol. Llega con calambres, potasio 3,0 mEq/L y frecuencia de 52. La tiazida causó hipopotasemia y el betabloqueador puede estar contribuyendo a la bradicardia. El caso exige ajustar ambos sin perder el control."},"objetivos":["Reconocer la hipopotasemia por tiazida y su manejo.","Elegir un betabloqueador en angina con bradicardia.","Priorizar seguridad y adherencia.","Diseñar un plan de seguimiento."],"conceptos":[{"icono":"Droplets","termino":"Hipopotasemia","definicion":"Potasio bajo por tiazida; puede causar arritmias y debilidad."},{"icono":"Activity","termino":"Angina","definicion":"Dolor por isquemia miocárdica; el betabloqueador reduce la demanda."},{"icono":"AlertTriangle","termino":"Bradicardia","definicion":"Frecuencia baja; límite para betabloqueador."},{"icono":"RefreshCw","termino":"Ajuste","definicion":"Cambiar dosis o fármaco según electrolitos y frecuencia."}],"secciones":[{"titulo":"Hipopotasemia","parrafos":["La tiazida aumenta la pérdida urinaria de potasio. La hipopotasemia puede causar debilidad, calambres, estreñimiento y arritmias. Se corrige con suplementos o con combinación con un ahorrador de potasio o IECA/ARA-II, según el caso. Se revisa el magnesio, porque la hipomagnesemia dificulta la corrección.","Si la paciente toma digoxina o tiene cardiopatía, la hipopotasemia es más peligrosa. Se debe corregir antes de ajustar otros fármacos."]},{"titulo":"Betabloqueador y angina","parrafos":["El atenolol puede causar bradicardia y fatiga. En angina, el betabloqueador es útil, pero se elige uno cardioselectivo y se titula según frecuencia y síntomas. Si la frecuencia es 52 y hay síntomas, se reduce la dosis o se cambia. No se suspende bruscamente.","Se revisa la presión, la frecuencia y los síntomas de isquemia. La educación incluye no suspender de golpe y reportar mareo o falta de aire."]},{"titulo":"Plan integrado","parrafos":["Se corrige el potasio, se ajusta la tiazida y se revisa el betabloqueador. Se controlan electrolitos, frecuencia y presión. La paciente debe entender qué cambios se hicieron y por qué.","El QF documenta y coordina con el equipo. La seguridad y la continuidad son prioritarias."]}],"errores":[{"error":"Ignorar la hipopotasemia.","correccion":"Puede causar arritmias."},{"error":"Suspender betabloqueador bruscamente.","correccion":"Riesgo de angina de rebote."},{"error":"No revisar magnesio.","correccion":"La hipomagnesemia dificulta la corrección."}],"comprueba":[{"pregunta":"¿Qué causa la hipopotasemia?","respuesta":"La tiazida, por pérdida urinaria."},{"pregunta":"¿Qué hacer con bradicardia sintomática?","respuesta":"Reducir o cambiar el betabloqueador, sin suspender bruscamente."},{"pregunta":"¿Qué se controla?","respuesta":"Potasio, magnesio, frecuencia y presión."}],"resumen":["La tiazida puede causar **hipopotasemia**.","El betabloqueador puede causar bradicardia.","Se corrige y ajusta de forma escalonada.","No se suspende bruscamente."],"referencias":[{"cita":"European Society of Cardiology. 2024 ESC Guidelines for the management of elevated blood pressure and hypertension. Eur Heart J. 2024.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Hypertension"},{"cita":"AEMPS-CIMA. Ficha técnica de Hidroclorotiazida.","url":"https://cima.aemps.es/cima/dochtml/ft/90833/FT_90833.html"}],"imagenes":[{"ubicacion":"Sección del caso","descripcion":"Paciente con calambres, potasio 3,0 y frecuencia 52, con tiazida y atenolol.","alt":"Caso de hipopotasemia por tiazida y betabloqueador"}],"keywords":["hipopotasemia tiazida","betabloqueador angina","bradicardia atenolol","caso clínico hipertensión"],"mapa":{"centro":"Tiazida y betabloqueador","ramas":[{"titulo":"Potasio","icono":"Droplets","nodos":["3,0","Calambres","Corregir"]},{"titulo":"Frecuencia","icono":"Activity","nodos":["52","Bradicardia","Ajustar"]},{"titulo":"Angina","icono":"Target","nodos":["Betabloqueador","Control","Evitar rebote"]},{"titulo":"Plan","icono":"RefreshCw","nodos":["Cambiar tiazida","Ajustar beta","Seguir"]}]},"proceso":{"titulo":"Abordaje de la paciente","intro":"","pasos":[{"titulo":"Evaluar potasio","detalle":"Síntomas, magnesio y riesgo de arritmia.","icono":"Droplets","evidencia":"Resultado."},{"titulo":"Corregir","detalle":"Suplemento o cambio de diurético.","icono":"Pill","evidencia":"Plan."},{"titulo":"Revisar beta","detalle":"Frecuencia, angina y síntomas.","icono":"Activity","evidencia":"Evaluación."},{"titulo":"Ajustar","detalle":"Dosis o cambio.","icono":"RefreshCw","evidencia":"Ajuste."},{"titulo":"Seguir","detalle":"Potasio, frecuencia y presión.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Potasio 3,0 y frecuencia 52","contexto":"Paciente con hidroclorotiazida, amlodipino y atenolol; calambres, potasio 3,0, frecuencia 52, angina estable.","pregunta":"¿Qué hacer primero?","opciones":[{"texto":"Aumentar el atenolol.","correcta":false,"retro":"Empeora la bradicardia."},{"texto":"Corregir el potasio, revisar la tiazida y ajustar el betabloqueador según síntomas.","correcta":true,"retro":"La seguridad primero: electrolitos y frecuencia."},{"texto":"Suspender todo.","correcta":false,"retro":"Se ajusta, no se abandona."}]}}$j$::jsonb;
