  -- 08. Introducción a la unidad: algoritmos de tratamiento y protocolos estandarizados
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El algoritmo no trata al paciente","texto":"Los algoritmos ayudan a ordenar decisiones, pero no reemplazan el juicio clínico. Un paciente con hipertensión y embarazo, otro con enfermedad renal y otro con HTA resistente no siguen el mismo camino. Conocer el algoritmo permite adaptarlo, no aplicarlo a ciegas."},"objetivos":["Explicar el algoritmo general de tratamiento.","Reconocer las combinaciones iniciales.","Identificar los escenarios que cambian el algoritmo.","Aplicar protocolos con criterio."],"conceptos":[{"icono":"Route","termino":"Algoritmo","definicion":"Secuencia de decisiones basada en evidencia y contexto."},{"icono":"Layers","termino":"Combinación","definicion":"Uso de dos o más fármacos con mecanismos complementarios."},{"icono":"Target","termino":"Meta","definicion":"Presión objetivo individualizada."},{"icono":"Users","termino":"Contexto","definicion":"Embarazo, ERC, fragilidad, resistencia y acceso."}],"secciones":[{"titulo":"Algoritmo general","parrafos":["El tratamiento comienza con estilo de vida y, cuando está indicado, con fármacos. En la mayoría de los pacientes se prefiere una combinación inicial de dos fármacos, especialmente si la presión está muy por encima de la meta. Las combinaciones más usadas son IECA o ARA-II con calcioantagonista o con tiazida.","La elección depende de la edad, la comorbilidad, la función renal, el embarazo y la tolerancia. La meta se individualiza y se revisa. Si no se alcanza, se intensifica de forma escalonada."]},{"titulo":"Escenarios que cambian el algoritmo","parrafos":["El embarazo excluye IECA, ARA-II y espironolactona; se usan otros fármacos. La enfermedad renal requiere ajuste y control de potasio. La fragilidad exige metas menos estrictas y vigilancia de hipotensión. La HTA resistente obliga a confirmar adherencia, descartar causas secundarias y considerar espironolactona.","El algoritmo es una guía, no una camisa de fuerza. La decisión se comparte con el paciente y se adapta a la realidad."]},{"titulo":"Protocolos y calidad","parrafos":["Los protocolos estandarizados mejoran la consistencia y la seguridad. Deben incluir medición, metas, combinaciones, controles y derivación. El QF puede participar en su implementación y en la auditoría.","La educación del equipo y del paciente es parte del protocolo. La medición correcta y la adherencia son prioridades."]}],"errores":[{"error":"Aplicar el algoritmo sin contexto.","correccion":"Embarazo, ERC y fragilidad cambian la decisión."},{"error":"No revisar adherencia antes de intensificar.","correccion":"La pseudorresistencia es frecuente."},{"error":"No individualizar la meta.","correccion":"La meta depende del riesgo y la tolerancia."}],"comprueba":[{"pregunta":"¿Cuál es la combinación inicial más usada?","respuesta":"IECA/ARA-II con calcioantagonista o tiazida."},{"pregunta":"¿Qué fármacos se evitan en el embarazo?","respuesta":"IECA, ARA-II y espironolactona."},{"pregunta":"¿Qué hacer antes de intensificar?","respuesta":"Revisar adherencia, medición y causas secundarias."}],"resumen":["El algoritmo ordena, no reemplaza el juicio.","La combinación inicial es frecuente.","El contexto cambia la decisión.","La adherencia se revisa antes de intensificar."],"referencias":[{"cita":"European Society of Cardiology. 2024 ESC Guidelines for the management of elevated blood pressure and hypertension. Eur Heart J. 2024.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Hypertension"},{"cita":"Organización Mundial de la Salud. Hipertensión: datos y cifras.","url":"https://www.who.int/es/news-room/fact-sheets/detail/hypertension"}],"imagenes":[{"ubicacion":"Sección del algoritmo","descripcion":"Diagrama de flujo desde estilo de vida hasta combinación y HTA resistente.","alt":"Algoritmo de tratamiento de la hipertensión"}],"keywords":["algoritmo hipertensión","tratamiento inicial hipertensión","combinación antihipertensiva","protocolo hipertensión"],"mapa":{"centro":"Algoritmo de HTA","ramas":[{"titulo":"Inicio","icono":"Route","nodos":["Estilo de vida","Monoterapia","Combinación"]},{"titulo":"Combinación","icono":"Layers","nodos":["IECA/ARA-II + Ca","IECA/ARA-II + tiazida"]},{"titulo":"Escenarios","icono":"Users","nodos":["Embarazo","ERC","Fragilidad"]},{"titulo":"Resistente","icono":"AlertTriangle","nodos":["Adherencia","Espironolactona","Derivación"]}]},"proceso":{"titulo":"Cómo aplicar el algoritmo","intro":"","pasos":[{"titulo":"Evaluar","detalle":"Presión, riesgo, comorbilidad y meta.","icono":"Search","evidencia":"Evaluación."},{"titulo":"Iniciar","detalle":"Estilo de vida y fármacos.","icono":"Pill","evidencia":"Plan."},{"titulo":"Combinar","detalle":"IECA/ARA-II + Ca o tiazida.","icono":"Layers","evidencia":"Esquema."},{"titulo":"Revisar","detalle":"Presión, tolerancia y adherencia.","icono":"CalendarClock","evidencia":"Control."},{"titulo":"Intensificar","detalle":"Escalonado o derivar.","icono":"Route","evidencia":"Ajuste."}]},"caso":{"titulo":"Presión 170/100 sin tratamiento","contexto":"Paciente sin tratamiento, presión 170/100, sin embarazo ni ERC.","pregunta":"¿Qué estrategia inicial es razonable?","opciones":[{"texto":"Monoterapia a dosis baja y esperar seis meses.","correcta":false,"retro":"La presión está muy por encima de la meta; la combinación inicial es más eficaz."},{"texto":"Combinación inicial de dos fármacos y estilo de vida.","correcta":true,"retro":"En hipertensión marcada, la combinación mejora el control."},{"texto":"Cinco fármacos de inicio.","correcta":false,"retro":"No es necesario; se escalona."}]}}$j$::jsonb;
