  -- 09. Terapia combinada inicial y combinaciones en dosis fija
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Dos fármacos en una pastilla","texto":"Las combinaciones en dosis fija simplifican el tratamiento y mejoran la adherencia. Pero no todas las combinaciones son equivalentes: IECA/ARA-II con calcioantagonista o tiazida tienen buena evidencia; IECA con ARA-II no se recomienda. Conocer las combinaciones racionales evita errores y mejora el control."},"objetivos":["Reconocer las combinaciones racionales.","Aplicar la terapia combinada inicial.","Ventajas y límites de las dosis fijas.","Revisar adherencia y seguridad."],"conceptos":[{"icono":"Layers","termino":"Dosis fija","definicion":"Dos fármacos en un solo comprimido; simplifica la toma."},{"icono":"Target","termino":"Sinergia","definicion":"Mecanismos complementarios que mejoran la eficacia y reducen efectos adversos."},{"icono":"AlertTriangle","termino":"Combinación no recomendada","definicion":"IECA con ARA-II aumenta el riesgo sin beneficio."},{"icono":"Users","termino":"Adherencia","definicion":"La simplificación puede mejorar el cumplimiento."}],"secciones":[{"titulo":"Combinaciones racionales","parrafos":["Las combinaciones de IECA o ARA-II con calcioantagonista o tiazida son eficaces y tienen evidencia. El bloqueo del sistema renina-angiotensina contrarresta la activación refleja y reduce el riesgo de hipopotasemia de la tiazida. La combinación de calcioantagonista y tiazida también es útil.","No se recomienda combinar IECA con ARA-II. La combinación de betabloqueador con verapamilo o diltiazem puede causar bradicardia y bloqueo; se evita en muchos contextos."]},{"titulo":"Dosis fija","parrafos":["Las dosis fijas reducen el número de comprimidos y pueden mejorar la adherencia. Sin embargo, limitan el ajuste independiente de cada componente y pueden no estar cubiertas. Se eligen cuando la combinación y las dosis son adecuadas para el paciente.","El QF puede revisar la cobertura, el costo y la adherencia. La simplificación debe acompañarse de educación."]},{"titulo":"Seguridad y seguimiento","parrafos":["Se controlan presión, función renal y electrolitos. La combinación puede aumentar el riesgo de hipotensión al inicio. Se titula de forma gradual y se revisa la tolerancia.","La educación incluye no suspender y reportar mareo o deshidratación. La meta se individualiza."]}],"errores":[{"error":"Combinar IECA y ARA-II.","correccion":"No se recomienda."},{"error":"No revisar cobertura.","correccion":"La dosis fija puede no estar cubierta."},{"error":"No controlar electrolitos.","correccion":"Riesgo de hiperpotasemia o hipopotasemia."}],"comprueba":[{"pregunta":"¿Qué combinaciones son racionales?","respuesta":"IECA/ARA-II con calcioantagonista o tiazida."},{"pregunta":"¿Qué combinación se evita?","respuesta":"IECA con ARA-II."},{"pregunta":"¿Qué ventaja tiene la dosis fija?","respuesta":"Menos pastillas y mejor adherencia."}],"resumen":["La combinación inicial es frecuente.","IECA/ARA-II + Ca o tiazida es racional.","IECA + ARA-II no se recomienda.","La dosis fija simplifica, pero limita el ajuste."],"referencias":[{"cita":"European Society of Cardiology. 2024 ESC Guidelines for the management of elevated blood pressure and hypertension. Eur Heart J. 2024.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Hypertension"},{"cita":"AEMPS-CIMA. Ficha técnica de Hidroclorotiazida.","url":"https://cima.aemps.es/cima/dochtml/ft/90833/FT_90833.html"}],"imagenes":[{"ubicacion":"Sección de combinaciones","descripcion":"Matriz de combinaciones racionales y no recomendadas.","alt":"Combinaciones de antihipertensivos"}],"keywords":["combinación antihipertensiva","dosis fija hipertensión","ieca ara-ii combinación","terapia combinada hipertensión"],"mapa":{"centro":"Combinaciones","ramas":[{"titulo":"Racionales","icono":"Layers","nodos":["IECA/ARA-II + Ca","IECA/ARA-II + tiazida"]},{"titulo":"No recomendadas","icono":"AlertTriangle","nodos":["IECA + ARA-II","Beta + no dihidropiridina"]},{"titulo":"Ventajas","icono":"CheckCircle2","nodos":["Menos pastillas","Adherencia","Costo"]},{"titulo":"Límites","icono":"Search","nodos":["Ajuste difícil","Cobertura","Efectos"]}]},"proceso":{"titulo":"Cómo elegir una combinación","intro":"","pasos":[{"titulo":"Evaluar","detalle":"Presión, comorbilidad y meta.","icono":"Target","evidencia":"Evaluación."},{"titulo":"Elegir","detalle":"IECA/ARA-II + Ca o tiazida.","icono":"Layers","evidencia":"Selección."},{"titulo":"Revisar","detalle":"Cobertura y dosis fija.","icono":"Calculator","evidencia":"Acceso."},{"titulo":"Educar","detalle":"Toma, efectos y adherencia.","icono":"Users","evidencia":"Educación."},{"titulo":"Seguir","detalle":"Presión, electrolitos y tolerancia.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"IECA + ARA-II","contexto":"Paciente con presión alta y prescripción de enalapril más losartán.","pregunta":"¿Qué hacer?","opciones":[{"texto":"Dispensar porque baja más la presión.","correcta":false,"retro":"La combinación no se recomienda por riesgo renal y de hiperpotasemia."},{"texto":"Consultar al prescriptor y proponer una combinación racional.","correcta":true,"retro":"Se evita la combinación y se elige otra."},{"texto":"Añadir un tercer bloqueador.","correcta":false,"retro":"No resuelve el problema."}]}}$j$::jsonb;
