  -- 10. HTA resistente: pseudorresistencia, causas secundarias, espironolactona y denervación renal
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La presión que no baja con tres fármacos","texto":"Un paciente toma tres antihipertensivos, incluido un diurético, y la presión sigue en 158/96. Antes de añadir un cuarto fármaco, hay que confirmar que toma el tratamiento, que la medición es correcta y que no hay una causa secundaria. La HTA resistente es un diagnóstico de exclusión."},"objetivos":["Definir HTA resistente y pseudorresistencia.","Reconocer causas secundarias frecuentes.","Aplicar el papel de la espironolactona.","Identificar el lugar de la denervación renal."],"conceptos":[{"icono":"AlertTriangle","termino":"HTA resistente","definicion":"Presión no controlada con tres fármacos, incluido un diurético, con adherencia y medición correctas."},{"icono":"Search","termino":"Pseudorresistencia","definicion":"Falta de control por adherencia, técnica, bata blanca o fármacos que elevan la presión."},{"icono":"Droplets","termino":"Causa secundaria","definicion":"Apnea del sueño, aldosteronismo, enfermedad renal, estenosis renal o fármacos."},{"icono":"Pill","termino":"Espironolactona","definicion":"Cuarta línea con evidencia en HTA resistente."}],"secciones":[{"titulo":"Pseudorresistencia","parrafos":["La pseudorresistencia es la causa más frecuente de “resistencia”. Incluye mala adherencia, técnica incorrecta, efecto de bata blanca, manguito inadecuado y fármacos que elevan la presión, como AINE, corticoides, descongestionantes, anticonceptivos y algunos antidepresivos.","Antes de intensificar, se revisa la adherencia con una entrevista sin juicio, se confirma la medición con AMPA o MAPA y se revisan los medicamentos. La educación y la simplificación pueden resolver el problema."]},{"titulo":"Causas secundarias","parrafos":["Las causas secundarias incluyen apnea obstructiva del sueño, hiperaldosteronismo primario, enfermedad renal, estenosis de la arteria renal, feocromocitoma, síndrome de Cushing y coartación de aorta. Los signos de sospecha incluyen hipopotasemia espontánea, resistencia a múltiples fármacos, inicio joven, empeoramiento abrupto y síntomas específicos.","La evaluación se individualiza. La apnea y el aldosteronismo son las más frecuentes. El QF puede detectar hipopotasemia y revisar los medicamentos."]},{"titulo":"Espironolactona y denervación","parrafos":["La espironolactona es la cuarta línea con mejor evidencia en HTA resistente. Se controlan potasio y función renal. La denervación renal es una opción especializada para pacientes seleccionados; no es un tratamiento de primera línea y requiere evaluación por especialistas.","La derivación a hipertensión especializada es apropiada en resistencia confirmada, causas secundarias sospechadas o intolerancia a múltiples fármacos."]}],"errores":[{"error":"Intensificar sin confirmar adherencia.","correccion":"La pseudorresistencia es frecuente."},{"error":"No buscar causas secundarias.","correccion":"Hipopotasemia, apnea y renal son claves."},{"error":"Usar espironolactona con potasio alto.","correccion":"Riesgo de hiperpotasemia."}],"comprueba":[{"pregunta":"¿Qué es HTA resistente?","respuesta":"Presión no controlada con tres fármacos, incluido un diurético, con adherencia y medición correctas."},{"pregunta":"¿Qué es pseudorresistencia?","respuesta":"Falta de control por adherencia, técnica, bata blanca o fármacos."},{"pregunta":"¿Cuál es la cuarta línea con evidencia?","respuesta":"Espironolactona."}],"resumen":["La resistencia se confirma.","La pseudorresistencia es frecuente.","Las causas secundarias se buscan.","Espironolactona es la cuarta línea."],"referencias":[{"cita":"European Society of Cardiology. 2024 ESC Guidelines for the management of elevated blood pressure and hypertension. Eur Heart J. 2024.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Hypertension"},{"cita":"Williams B, MacDonald TM, Morant S, et al. Spironolactone versus placebo, bisoprolol, and doxazosin to determine the optimal treatment for drug-resistant hypertension (PATHWAY-2). Lancet. 2015;386(10008):2059-68.","url":"https://pubmed.ncbi.nlm.nih.gov/26314530/"}],"imagenes":[{"ubicacion":"Sección de resistencia","descripcion":"Diagrama de tres fármacos y un cuarto escalón con espironolactona, tras descartar pseudorresistencia.","alt":"Manejo de la hipertensión resistente"}],"keywords":["hipertensión resistente","pseudorresistencia hipertensión","espironolactona hta resistente","causas secundarias hipertensión","denervación renal"],"mapa":{"centro":"HTA resistente","ramas":[{"titulo":"Confirmar","icono":"Gauge","nodos":["Adherencia","Técnica","AMPA/MAPA"]},{"titulo":"Causas","icono":"Search","nodos":["Apnea","Aldosteronismo","Renal"]},{"titulo":"Tratar","icono":"Pill","nodos":["Espironolactona","Combinación","Derivación"]},{"titulo":"Avanzado","icono":"Activity","nodos":["Denervación","Investigación"]}]},"proceso":{"titulo":"Cómo abordar la HTA resistente","intro":"","pasos":[{"titulo":"Confirmar","detalle":"Medición, AMPA/MAPA y adherencia.","icono":"Gauge","evidencia":"Confirmación."},{"titulo":"Revisar fármacos","detalle":"AINE, corticoides, descongestionantes.","icono":"Search","evidencia":"Lista."},{"titulo":"Buscar causa","detalle":"Apnea, aldosteronismo, renal.","icono":"Search","evidencia":"Evaluación."},{"titulo":"Cuarta línea","detalle":"Espironolactona con control de potasio.","icono":"Pill","evidencia":"Plan."},{"titulo":"Derivar","detalle":"Si no se controla o hay causa secundaria.","icono":"Route","evidencia":"Remisión."}]},"caso":{"titulo":"Tres fármacos y presión alta","contexto":"Paciente con IECA, amlodipino e hidroclorotiazida, presión 158/96, adherencia dudosa y potasio 3,2.","pregunta":"¿Qué hacer primero?","opciones":[{"texto":"Añadir espironolactona de inmediato.","correcta":false,"retro":"Hay hipopotasemia y adherencia dudosa; primero se confirma y se corrige."},{"texto":"Confirmar adherencia y medición, revisar causas y corregir potasio antes de intensificar.","correcta":true,"retro":"La pseudorresistencia y las causas secundarias deben evaluarse."},{"texto":"Duplicar la tiazida.","correcta":false,"retro":"Empeora la hipopotasemia."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$HTA resistente: pseudorresistencia, causas secundarias, espironolactona y denervación renal$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$HTA resistente: pseudorresistencia, causas secundarias, espironolactona y denervación renal$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  IF v_n > 0 THEN
    INSERT INTO aula_republicaciones_aprobadas (course_id, aprobado_por, nota)
    SELECT v_curso, 'Dirección académica de Edvanta', 'Clases ampliadas con experiencia interactiva (130_experiencias_farmacoterapia_hta_2.sql).'
     WHERE EXISTS (SELECT 1 FROM aula_courses WHERE id = v_curso AND current_version_id IS NOT NULL);
  END IF;

  RAISE NOTICE 'Experiencias de %: % clases.', $t$Curso de Farmacoterapia de la Hipertensión Arterial$t$, v_n;
END $exp$;
